1. use std::process::{Command, Output};
2. 
3. const USAGE: &str = "Usage:\n  routebook list\n  routebook search [--name TEXT] [--max-distance KM] [--difficulty easy|moderate|hard]\n";
4. 
5. const FERN_LOOP: &str = "Fern Loop | 3.2 km | easy";
6. const NORTH_RIDGE: &str = "North Ridge | 11.5 km | hard";
7. const LAKE_CIRCUIT: &str = "Lake Circuit | 7.0 km | moderate";
8. const FERN_VALLEY: &str = "Fern Valley | 8.5 km | moderate";
9. const SUMMIT: &str = "Summit Traverse | 16.0 km | hard";
10. const ALL: [&str; 5] = [FERN_LOOP, NORTH_RIDGE, LAKE_CIRCUIT, FERN_VALLEY, SUMMIT];
11. 
12. fn run(args: &[&str]) -> Output {
13.     Command::new(env!("CARGO_BIN_EXE_routebook"))
14.         .args(args)
15.         .output()
16.         .expect("failed to run routebook")
17. }
18. 
19. fn assert_ok(args: &[&str], expected: &[&str]) {
20.     let out = run(args);
21.     let want: String = expected.iter().map(|r| format!("{r}\n")).collect();
22.     assert_eq!(out.status.code(), Some(0), "args {args:?}");
23.     assert_eq!(String::from_utf8_lossy(&out.stdout), want, "args {args:?}");
24.     assert_eq!(String::from_utf8_lossy(&out.stderr), "", "args {args:?}");
25. }
26. 
27. fn assert_usage_error(args: &[&str]) {
28.     let out = run(args);
29.     assert_eq!(out.status.code(), Some(2), "args {args:?}");
30.     assert_eq!(String::from_utf8_lossy(&out.stdout), "", "args {args:?}");
31.     let err = String::from_utf8_lossy(&out.stderr).into_owned();
32.     assert!(err.starts_with("error: "), "args {args:?}: {err:?}");
33.     assert!(err.ends_with(USAGE), "args {args:?}: {err:?}");
34. }
35. 
36. #[test]
37. fn list_preserves_catalogue_order() {
38.     assert_ok(&["list"], &ALL);
39. }
40. 
41. #[test]
42. fn search_without_filters_matches_list() {
43.     assert_ok(&["search"], &ALL);
44. }
45. 
46. #[test]
47. fn name_filter_is_case_insensitive_substring() {
