49.         assert_ok(&["search", "--name", name], &[FERN_LOOP, FERN_VALLEY]);
50.     }
51.     assert_ok(&["search", "--name", "RIDGE"], &[NORTH_RIDGE]);
52. }
53. 
54. #[test]
55. fn empty_name_matches_everything() {
56.     assert_ok(&["search", "--name", ""], &ALL);
57. }
58. 
59. #[test]
60. fn distance_filter_is_inclusive_and_ordered() {
61.     assert_ok(
62.         &["search", "--max-distance", "8.5"],
63.         &[FERN_LOOP, LAKE_CIRCUIT, FERN_VALLEY],
64.     );
65.     assert_ok(&["search", "--max-distance", "3.2"], &[FERN_LOOP]);
66.     assert_ok(&["search", "--max-distance", "16"], &ALL);
67.     assert_ok(
68.         &["search", "--max-distance", "8.4"],
