72. }
73. 
74. #[test]
75. fn zero_distance_is_valid_and_matches_nothing() {
76.     assert_ok(&["search", "--max-distance", "0"], &[]);
77. }
78. 
79. #[test]
80. fn difficulty_filter_is_case_insensitive() {
81.     assert_ok(&["search", "--difficulty", "easy"], &[FERN_LOOP]);
82.     assert_ok(
