1. use std::fmt;
2. 
3. #[derive(Clone, Copy, Debug, PartialEq, Eq)]
4. pub enum Difficulty {
5.     Easy,
6.     Moderate,
7.     Hard,
8. }
9. 
10. impl fmt::Display for Difficulty {
11.     fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
12.         formatter.write_str(match self {
13.             Self::Easy => "easy",
14.             Self::Moderate => "moderate",
15.             Self::Hard => "hard",
16.         })
17.     }
18. }
19. 
20. #[derive(Clone, Debug, PartialEq)]
21. pub struct Route {
22.     pub name: &'static str,
23.     pub distance_km: f64,
24.     pub difficulty: Difficulty,
25. }
26. 
27. pub fn catalogue() -> Vec<Route> {
28.     vec![
29.         Route {
30.             name: "Fern Loop",
31.             distance_km: 3.2,
32.             difficulty: Difficulty::Easy,
33.         },
34.         Route {
35.             name: "North Ridge",
36.             distance_km: 11.5,
37.             difficulty: Difficulty::Hard,
38.         },
39.         Route {
40.             name: "Lake Circuit",
41.             distance_km: 7.0,
42.             difficulty: Difficulty::Moderate,
43.         },
44.         Route {
45.             name: "Fern Valley",
46.             distance_km: 8.5,
47.             difficulty: Difficulty::Moderate,
48.         },
49.         Route {
50.             name: "Summit Traverse",
51.             distance_km: 16.0,
52.             difficulty: Difficulty::Hard,
53.         },
54.     ]
55. }
56. 
57. pub fn display_route(route: &Route) -> String {
58.     format!(
59.         "{} | {:.1} km | {}",
60.         route.name, route.distance_km, route.difficulty
61.     )
62. }
63. 
64. /// Composable route filter; unset criteria match everything.
65. #[derive(Clone, Debug, Default, PartialEq)]
66. pub struct SearchFilter {
67.     name_contains: Option<String>,
68.     max_distance_km: Option<f64>,
69.     difficulty: Option<Difficulty>,
70. }
71. 
72. impl SearchFilter {
73.     pub fn new() -> Self {
74.         Self::default()
75.     }
76. 
77.     /// Case-insensitive name substring. An empty string matches every name.
78.     pub fn name_contains(mut self, text: impl Into<String>) -> Self {
79.         self.name_contains = Some(text.into().to_lowercase());
80.         self
81.     }
82. 
83.     /// Inclusive maximum distance. NaN or negative values match no routes.
84.     pub fn max_distance_km(mut self, km: f64) -> Self {
85.         self.max_distance_km = Some(km);
86.         self
87.     }
88. 
89.     pub fn difficulty(mut self, difficulty: Difficulty) -> Self {
90.         self.difficulty = Some(difficulty);
91.         self
92.     }
93. 
94.     pub fn matches(&self, route: &Route) -> bool {
95.         self.name_contains
96.             .as_ref()
97.             .is_none_or(|text| route.name.to_lowercase().contains(text.as_str()))
98.             && self
99.                 .max_distance_km
100.                 .is_none_or(|max| route.distance_km <= max)
101.             && self.difficulty.is_none_or(|d| route.difficulty == d)
102.     }
103. }
104. 
105. /// Returns matching routes borrowed from `routes`, in their original order.
106. pub fn search<'a>(routes: &'a [Route], filter: &SearchFilter) -> Vec<&'a Route> {
107.     routes
108.         .iter()
109.         .filter(|route| filter.matches(route))
110.         .collect()
111. }
112. 
113. #[cfg(test)]
114. mod tests {
115.     use super::*;
116. 
117.     fn names(found: &[&Route]) -> Vec<&'static str> {
118.         found.iter().map(|route| route.name).collect()
119.     }
120. 
121.     #[test]
122.     fn empty_filter_returns_all_in_order() {
123.         let routes = catalogue();
124.         let found = search(&routes, &SearchFilter::new());
125.         assert_eq!(found.len(), routes.len());
126.         assert!(found.iter().zip(&routes).all(|(a, b)| std::ptr::eq(*a, b)));
127.     }
128. 
129.     #[test]
130.     fn name_is_case_insensitive_substring() {
131.         let routes = catalogue();
132.         let found = search(&routes, &SearchFilter::new().name_contains("FERN"));
133.         assert_eq!(names(&found), ["Fern Loop", "Fern Valley"]);
134.     }
135. 
136.     #[test]
137.     fn max_distance_is_inclusive() {
138.         let routes = catalogue();
139.         let found = search(&routes, &SearchFilter::new().max_distance_km(8.5));
140.         assert_eq!(names(&found), ["Fern Loop", "Lake Circuit", "Fern Valley"]);
141.     }
142. 
143.     #[test]
144.     fn difficulty_filters() {
145.         let routes = catalogue();
146.         let found = search(&routes, &SearchFilter::new().difficulty(Difficulty::Hard));
147.         assert_eq!(names(&found), ["North Ridge", "Summit Traverse"]);
148.     }
149. 
150.     #[test]
151.     fn combined_filters_all_apply() {
152.         let routes = catalogue();
153.         let filter = SearchFilter::new()
154.             .name_contains("fern")
155.             .max_distance_km(8.5)
156.             .difficulty(Difficulty::Moderate);
157.         assert_eq!(names(&search(&routes, &filter)), ["Fern Valley"]);
158.         let none = filter.max_distance_km(8.4);
159.         assert!(search(&routes, &none).is_empty());
160.     }
